import{_ as s,o as a,c as e,a3 as t}from"./chunks/framework.CVt6dz2a.js";const c=JSON.parse('{"title":"EP.01 第一个三维场景","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.01-first-scene.md","filePath":"comics/EP.01-first-scene.md","lastUpdated":1792595797000}'),n={name:"comics/EP.01-first-scene.md"};function h(l,i,r,d,o,p){return a(),e("div",null,[...i[0]||(i[0]=[t(`<h1 id="ep-01-第一个三维场景" tabindex="-1">EP.01 第一个三维场景 <a class="header-anchor" href="#ep-01-第一个三维场景" aria-label="Permalink to &quot;EP.01 第一个三维场景&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/01-intro/basics">1.1 基础入门：Three.js 是什么与第一个场景</a> 延伸阅读：<a href="./../guide/01-intro/advanced">进阶篇</a> · <a href="./../guide/01-intro/practice">实战篇</a> 动手演示：<a href="./../public/demos/intro/hello-cube.html">hello-cube 第一个场景</a> · <a href="./../public/demos/intro/template.html">template 最小模板</a> · <a href="./../public/demos/intro/debugging.html">debugging 黑屏排查台</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>标签君抄完 Hello Cube，屏幕一片黑：Mesh 建了、灯也&quot;觉得&quot;加了，就是什么都没有。</td></tr><tr><td>② 揭秘</td><td>码叔摆出渲染管线四件套：<strong>Scene 场景、Camera 相机、Renderer 渲染器、Mesh 物体</strong>，少一环都不亮。</td></tr><tr><td>③ 实证</td><td>像素酱把相机挪到 (3,2,4)、补上 <code>scene.add(cube)</code>，再用一盏灯配合 Standard 材质，立方体终于转了起来。</td></tr><tr><td>④ 结案</td><td>码叔总结黑屏排查清单：没 add、相机扎进物体、材质要灯没灯、near 设成 0。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-黑屏四件套-任何-three-js-程序的最小闭环" tabindex="-1">① 黑屏四件套：任何 Three.js 程序的最小闭环 <a class="header-anchor" href="#_1-黑屏四件套-任何-three-js-程序的最小闭环" aria-label="Permalink to &quot;① 黑屏四件套：任何 Three.js 程序的最小闭环&quot;">​</a></h3><p>Three.js 不是游戏引擎，而是 WebGL 的高层封装。一个能出画面的程序必须同时具备：</p><ol><li><code>Scene</code>——场景树的根，所有可见物体的容器；</li><li><code>Camera</code>——观察者，决定从哪里看、怎么投影；</li><li><code>WebGLRenderer</code>——把场景画到 <code>&lt;canvas&gt;</code> 上；</li><li><code>Mesh</code>——真正摆在场景里的物体，由 <strong>Geometry（形状）+ Material（外观）</strong> 组成。</li></ol><p>四者的连接关系固定：<code>renderer.render(scene, camera)</code> 每帧执行一次，而 mesh 必须已经 <code>scene.add()</code> 进场景树。</p><h3 id="_2-mesh-创建了不会自动出现" tabindex="-1">② Mesh 创建了不会自动出现 <a class="header-anchor" href="#_2-mesh-创建了不会自动出现" aria-label="Permalink to &quot;② Mesh 创建了不会自动出现&quot;">​</a></h3><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> cube</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> THREE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Mesh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> THREE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BoxGeometry</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> THREE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MeshStandardMaterial</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scene.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(cube) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 漏掉这行 = 屏幕一片黑</span></span></code></pre></div><p>Three.js 只渲染场景树上的节点。new 出来的对象只是游离在内存里，<code>add</code> 才是把它挂到树上。</p><h3 id="_3-相机不能和物体重合" tabindex="-1">③ 相机不能和物体重合 <a class="header-anchor" href="#_3-相机不能和物体重合" aria-label="Permalink to &quot;③ 相机不能和物体重合&quot;">​</a></h3><p>立方体中心默认在原点 (0,0,0)，相机也在原点就是&quot;扎&quot;进几何体内部，看到的只有内表面（通常被背面剔除，画面全黑）。起步固定动作：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">camera.position.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">camera.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lookAt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h3 id="_4-要灯的材质-没灯就是黑的" tabindex="-1">④ 要灯的材质，没灯就是黑的 <a class="header-anchor" href="#_4-要灯的材质-没灯就是黑的" aria-label="Permalink to &quot;④ 要灯的材质，没灯就是黑的&quot;">​</a></h3><p><code>MeshStandardMaterial</code> / <code>MeshLambertMaterial</code> 完全依赖灯光计算颜色，场景里没有任何光源时输出纯黑。两条路：</p><ul><li>学习起步用 <code>MeshNormalMaterial</code>（按法线自动配色）或 <code>MeshBasicMaterial</code>（纯色），不需要灯；</li><li>用 Standard 材质就加一盏 <code>HemisphereLight</code> 或 <code>DirectionalLight</code>。</li></ul><p>另外两个出厂设置建议：像素比钳制 <code>renderer.setPixelRatio(Math.min(devicePixelRatio, 2))</code>，避免高分屏 GPU 过载；窗口缩放后必须 <code>camera.updateProjectionMatrix()</code>。</p><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：near 能设成 0 吗？</strong> 不能。near 过小会让深度缓冲精度崩塌，出现 z-fighting 闪烁条纹。常规场景用 <code>0.1</code>，far 按实际需要设，别一上来 10000。</li><li><strong>Q：setAnimationLoop 和 requestAnimationFrame 选哪个？</strong> 优先 <code>setAnimationLoop</code>，它额外处理了页面隐藏暂停与 WebGL 上下文丢失恢复。</li><li><strong>Q：resize 后画面拉伸？</strong> 只改 <code>camera.aspect</code> 不够，必须调用 <code>camera.updateProjectionMatrix()</code>，再 <code>renderer.setSize()</code>。</li><li><strong>Q：文件双击打开（file://）演示页白屏？</strong> ES Module + importmap 在 file 协议下会被 CORS 拦截，请用本地静态服务器（<code>python3 -m http.server</code>）打开。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>下列哪种情况<strong>不会</strong>导致黑屏？（A. 忘记 <code>scene.add(mesh)</code> B. 相机放在原点 C. near 设为 0.1、far 设为 100 D. 用 Standard 材质但场景无灯）</li><li>Mesh 由哪两个部分组成？各自负责什么？</li><li>窗口大小变化时，除了 <code>renderer.setSize()</code> 还必须对相机做哪两步？</li></ol><details><summary>答案</summary><ol><li><strong>C</strong>。0.1/100 是合理的近远裁面；A、B、D 都是经典黑屏原因。</li><li><strong>Geometry 几何体</strong>负责形状（顶点/三角面数据），<strong>Material 材质</strong>负责外观（颜色、如何与光互动）。</li><li>重算 <code>camera.aspect = innerWidth / innerHeight</code>，然后调用 <strong><code>camera.updateProjectionMatrix()</code></strong>。</li></ol></details>`,24)])])}const E=s(n,[["render",h]]);export{c as __pageData,E as default};
